 c.limit=60;c.view={size:23,eye:[0,25,19],target:[0,0,0]};const solo=c.players[0];solo.x=0;solo.z=-8;let angle=0,range=9,hand=null,serial=0;c.players.slice(1).forEach((p,i)=>{p.x=(i-1)*4;p.z=2;p.heading=c.rand(0,TAU);p.goal={x:p.x,z:p.z};p.react=0;p.lag=c.rand(.2,.5);});const target=()=>({x:Math.sin(angle)*range,z:-8+Math.cos(angle)*range});
 return{update(dt){c.hint('1P 좌우 조준·아래/위로 거리 조절·A 던지기 / 물고기: 방향 지정+A 앞으로 수영');const fish=trio(c).sort((a,b)=>dist(a,target())-dist(b,target()))[0],want=fish?Math.atan2(fish.x,fish.z+8):0,wantR=fish?Math.hypot(fish.x,fish.z+8):8,q0=c.input(solo,()=>({x:clamp((want-angle)*3,-1,1),z:clamp((wantR-range)*1.5,-1,1),a:!hand&&!!fish&&dist(fish,target())<1.1}));angle=clamp(angle+q0.x*.95*dt,-.95,.95);range=clamp(range+q0.z*4*dt,3,14);if(q0.ap&&!hand){const p=target();hand={id:serial++,x:0,z:-8,y:1,tx:p.x,tz:p.z,origin:p,age:0,phase:'out',catch:null};}for(const p of trio(c)){p.react-=dt;if(p.react<=0){p.react=p.lag;const danger=hand?.phase==='out'&&dist(p,{x:hand.tx,z:hand.tz})<2.5;if(danger){const v=toward({x:hand.tx,z:hand.tz},p.x,p.z);p.goal={x:clamp(p.x+v.x*3,-7,7),z:clamp(p.z+v.z*3,-4.5,5.2)};}else if(dist(p,p.goal)<.7)p.goal={x:c.rand(-7,7),z:c.rand(-4.5,5.2)};}const q=c.input(p,()=>({...toward(p,p.goal.x,p.goal.z),a:true}));if(Math.hypot(q.x,q.z)>.2)p.heading=Math.atan2(q.x,q.z);if(q.a){p.x+=Math.sin(p.heading)*3.4*dt;p.z+=Math.cos(p.heading)*3.4*dt;}p.x=clamp(p.x,-7.5,7.5);p.z=clamp(p.z,-5,5.5);p.y=-.2;p.rotation=Math.PI/2-p.heading;p.pose='float';}if(hand){hand.age+=dt;if(hand.phase==='out'){hand.tx=clamp(hand.tx+q0.x*1.3*dt,hand.origin.x-1,hand.origin.x+1);hand.tz=clamp(hand.tz+q0.z*1.3*dt,hand.origin.z-1,hand.origin.z+1);const k=Math.min(1,hand.age/.65);hand.x=hand.tx*k;hand.z=-8+(hand.tz+8)*k;hand.y=1+Math.sin(k*Math.PI)*3.5;if(k===1){const hit=trio(c).filter(p=>dist(p,{x:hand.tx,z:hand.tz})<1).sort((a,b)=>dist(a,hand)-dist(b,hand))[0];if(hit){hand.catch=hit.i;c.eliminate(hit);}hand.phase='back';hand.age=0;hand.y=0;}}else{const k=Math.min(1,hand.age/.7);hand.x=hand.tx*(1-k);hand.z=hand.tz+(-8-hand.tz)*k;hand.y=k;if(k===1)hand=null;}}if(!trio(c).length)c.complete([0],'물고기 세 마리를 모두 낚았습니다');},render(){c.arena({width:19,depth:17,color:'#9fbf97'});c.draw('pool','box',{x:0,y:-.1,z:0,sx:17,sy:.15,sz:13,color:'#83bdcf'});const t=target();c.draw('aim','ring',{x:t.x,y:.03,z:t.z,sx:1.8,sy:1.8,sz:1,rx:-Math.PI/2,color:solo.color});if(hand){rope(c,'line',{x:0,y:1.7,z:-8},hand,cream);c.draw('glove','sphere',{x:hand.x,y:hand.y,z:hand.z,sx:1.1,sy:.6,sz:1.1,color:cream});}},timeout(){c.complete(trio(c).length?[1,2,3]:[0],'한 마리라도 남으면 물고기 팀 전체 승리');}};
