 c.limit=180;c.view={size:24,eye:[0,22,22],target:[0,0,0]};const length=140,gates=Array.from({length:14},(_,i)=>({d:12+i*8.5,blocked:c.shuffle([-1,0,1]).slice(0,c.rand()<.45?2:1),coin:c.int(-1,1)})),teams=[{d:0,speed:0,x:0,seen:new Set()},{d:0,speed:0,x:0,seen:new Set()}];c.players.forEach((p,i)=>{p.side=0;p.reaction=c.rand(.18,.4);p.goal=0;p.next=0;p.error=c.rand(.08,.17);p.plan=null;});
 return{update(dt){c.hint('두 사람 함께 좌우 조종 · 한 칸·두 칸 표지판을 피하고 코인을 모으며 결승선까지');const done=[];for(let i=0;i<2;i++){const t=teams[i],next=gates.find(g=>g.d>t.d),inputs=[];for(const p of c.players.slice(i*2,i*2+2)){if(p.plan!==next&&c.time>=p.next){p.plan=next;p.next=c.time+p.reaction;const safe=next?[-1,0,1].filter(l=>!next.blocked.includes(l)):[0];p.goal=c.rand()<p.error?c.int(-1,1):safe.sort((a,b)=>Math.abs(a-t.x)-Math.abs(b-t.x))[0];}inputs.push(c.input(p,()=>({x:clamp((p.goal-t.x)*3,-1,1)})));}t.x=clamp(t.x+(inputs[0].x+inputs[1].x)*1.6*dt,-1,1);t.speed=Math.min(8,t.speed+2.2*dt);const old=t.d;t.d+=t.speed*dt;for(let j=0;j<gates.length;j++){const g=gates[j];if(old<g.d&&t.d>=g.d&&!t.seen.has(j)){t.seen.add(j);if(g.blocked.some(l=>Math.abs(t.x-l)<.5))t.speed=1.8;if(Math.abs(t.x-g.coin)<.4)c.players.slice(i*2,i*2+2).forEach(p=>c.points(p));}}c.players.slice(i*2,i*2+2).forEach((p,j)=>{p.x=(i?5.7:-5.7)+t.x*2;p.z=3+j*1.4;p.y=.4;});if(t.d>=length)done.push({ids:[i*2,i*2+1],t:(length-old)/(t.d-old)});}finish(c,done,'표지판을 피해 코스터 결승선에 먼저 도착했습니다');},render(){c.arena({width:25,depth:22,color:'#8194b0'});teams.forEach((t,i)=>{const base=i?5.7:-5.7;for(let l=-1;l<=1;l++)c.draw('rail'+i+'_'+l,'box',{x:base+l*2,y:0,z:0,sx:.1,sy:.15,sz:22,color:cream});for(let j=0;j<gates.length;j++){const g=gates[j],z=3-(g.d-t.d)*.65;if(Math.abs(z)>11)continue;for(const l of g.blocked)c.draw('sign'+i+'_'+j+'_'+l,'box',{x:base+l*2,y:1,z,sx:1.65,sy:2,sz:.3,color:g.blocked.length===2?'#d0a283':'#b2a1bf'});if(!t.seen.has(j))c.draw('coin'+i+'_'+j,'cylinder',{x:base+g.coin*2,y:.6,z:z-1,sx:.55,sy:.1,sz:.55,rx:Math.PI/2,color:'#e2c16d'});}c.draw('car'+i,'box',{x:base+t.x*2,y:.2,z:3.7,sx:1.6,sy:.5,sz:3.2,color:c.players[i*2].color});label(c,'distance'+i,Math.ceil(length-t.d)+' m',base,4,-7,3);});},timeout(){c.complete([],'결승선에 도착한 팀이 없습니다');}};
